$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
function Binding {
 $ls=@(Get-CimInstance -Namespace 'root/StandardCimv2' -ClassName MSFT_NetTCPConnection -Filter '(LocalPort=8091 OR LocalPort=8095 OR LocalPort=8097 OR LocalPort=9600) AND State=2' -OperationTimeoutSec 3)
 if($ls.Count -gt 16){throw 'listener bound'}
 $rows=@(foreach($l in $ls){$proc=Get-CimInstance Win32_Process -Filter ('ProcessId='+[uint32]$l.OwningProcess) -Property ProcessId,CreationDate,ExecutablePath -OperationTimeoutSec 3; @{port=[int]$l.LocalPort;pid=[int]$proc.ProcessId;created=$proc.CreationDate.ToUniversalTime().ToString('o');exe=$proc.ExecutablePath}})
 ConvertTo-Json -InputObject $rows -Depth 4 -Compress
}

function Physical {
 $os=Get-CimInstance Win32_OperatingSystem -Property LastBootUpTime,TotalVisibleMemorySize,FreePhysicalMemory -OperationTimeoutSec 3
 $disk=Get-CimInstance Win32_LogicalDisk -Filter "DeviceID='C:'" -Property DeviceID,FreeSpace,Size,FileSystem -OperationTimeoutSec 3
 $vms=@(Get-VM|Select-Object Id,Name,State,MemoryAssigned,MemoryStartup,DynamicMemoryEnabled)
 if($vms.Count -gt 32){throw 'VM bound'}
 @{monotonicMilliseconds=[long][decimal]::Floor(([decimal][Diagnostics.Stopwatch]::GetTimestamp()*1000)/[Diagnostics.Stopwatch]::Frequency);atUtc=[DateTime]::UtcNow.ToString('o');boot=$os.LastBootUpTime.ToUniversalTime().ToString('o');physicalBytes=([int64]$os.TotalVisibleMemorySize*1024);freeBytes=([int64]$os.FreePhysicalMemory*1024);diskFreeBytes=[int64]$disk.FreeSpace;filesystem=$disk.FileSystem;vms=$vms}
}

